// ---------- funcoes de turno (iguais em todos os fluxos) ----------
function turnoDaHora(h) {
    if (h >= 6 && h < 14) return 'manha';
    if (h >= 14 && h < 22) return 'tarde';
    return 'noite';
}

function dataLocal(d) {
    var ano = d.getFullYear();
    var mes = String(d.getMonth() + 1).padStart(2, '0');
    var dia = String(d.getDate()).padStart(2, '0');
    return ano + '-' + mes + '-' + dia;
}

// Transforma o timestamp de uma lamina em { dia, turno } no horario local.
// O turno da noite (22h-6h) conta para o dia em que comecou.
function diaETurno(timestamp) {
    var momento = new Date(timestamp);
    if (isNaN(momento.getTime())) return null;
    var hora = momento.getHours();
    var diaProducao = new Date(momento.getTime());
    if (hora < 6) diaProducao.setDate(diaProducao.getDate() - 1);
    return { dia: dataLocal(diaProducao), turno: turnoDaHora(hora) };
}

// Le o resumo_turnos.csv: devolve as linhas e quais turnos ja foram fechados
function lerResumo(texto) {
    var linhas = [];
    var fechados = {};
    (texto || '').split(/\r?\n/).forEach(function (linha, i) {
        if (i === 0 || !linha.trim()) return; // pula cabecalho e linha vazia
        var c = linha.split(',');
        var registro = { dia: c[0], turno: c[1], esteira: c[2], total: parseInt(c[3], 10) || 0 };
        linhas.push(registro);
        fechados[registro.dia + '|' + registro.turno] = true;
    });
    return { linhas: linhas, fechados: fechados };
}

// Percorre o contagem.csv chamando fn(dia, turno, esteira) para cada lamina
function percorrerContagem(texto, fn) {
    var linhas = (texto || '').split(/\r?\n/);
    var cabecalho = (linhas[0] || '').split(',');
    var iEsteira = cabecalho.indexOf('esteira');
    var iTimestamp = cabecalho.indexOf('timestamp');
    if (iEsteira === -1 || iTimestamp === -1) return false;
    for (var i = 1; i < linhas.length; i++) {
        if (!linhas[i].trim()) continue;
        var c = linhas[i].split(',');
        var dt = diaETurno(c[iTimestamp]);
        if (!dt) continue;
        fn(dt.dia, dt.turno, c[iEsteira]);
    }
    return true;
}

// ---------- HISTORICO ----------
// Turnos fechados vem do resumo_turnos.csv (leve).
// O turno em andamento (e qualquer um ainda nao fechado) vem do contagem.csv.
var dias = parseInt(msg.req && msg.req.query ? msg.req.query.dias : '', 10);
if (!dias || dias < 1) dias = 7;
if (dias > 90) dias = 90;

var porDia = {};
function somar(dia, turno, esteira, quantidade) {
    if (!porDia[dia]) {
        porDia[dia] = { data: dia, total: 0, turnos: { manha: 0, tarde: 0, noite: 0 }, esteiras: {} };
    }
    var r = porDia[dia];
    r.total += quantidade;
    r.turnos[turno] = (r.turnos[turno] || 0) + quantidade;
    if (!r.esteiras[esteira]) r.esteiras[esteira] = { manha: 0, tarde: 0, noite: 0, total: 0 };
    r.esteiras[esteira][turno] += quantidade;
    r.esteiras[esteira].total += quantidade;
}

var resumo = lerResumo(msg.resumo);
resumo.linhas.forEach(function (l) { somar(l.dia, l.turno, l.esteira, l.total); });

percorrerContagem(typeof msg.payload === 'string' ? msg.payload : '', function (dia, turno, esteira) {
    if (resumo.fechados[dia + '|' + turno]) return; // ja contado pelo resumo
    somar(dia, turno, esteira, 1);
});

var lista = Object.keys(porDia).sort().reverse().slice(0, dias)
    .map(function (chave) { return porDia[chave]; });

msg.payload = { dias: lista };
return msg;

var texto = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
if (texto.indexOf('ENOENT') !== -1) {
    // contagem.csv ainda nao existe: sem historico, nao e erro
    msg.statusCode = 200;
    msg.payload = { dias: [] };
    return msg;
}
msg.statusCode = 500;
msg.payload = { erro: 'Falha no historico: ' + texto };
return msg;
